using System.IO;
using System.IO.Compression;
using System.Text.Json;
namespace MRS;
internal static class DiscoverySharingTests
{
 internal static void Run(Action<bool,string> check)
 {
  string root=Path.Combine(AppContext.BaseDirectory,"discovery-sharing-tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  var folder=new FrequencyItem{IsFolder=true,Name="DMR"};var channel=new FrequencyItem{ParentId=folder.Id,Name="Observed carrier",FrequencyHz=461413035,Protocols="DMR",SiteScope="DMR:Tier III:Network 5:Site 11",Signaling="Network 5; Site 11; CC 4",Notes="My private notes",Activity=new(DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,1,12500,10,"Private receiver")};
  check(DiscoveryNames.Label(channel)=="DMR · Net 5 · Site 11 · CC 4","Discovery marker uses known network/site/CC");check(DiscoveryNames.Label(channel with{Name="My repeater"})=="My repeater","Custom spectrum labels remain authoritative");
  check(DiscoveryNames.Frequency(461412500)=="461.4125"&&DiscoveryNames.Frequency(451006250)=="451.00625","Frequency formatting trims zeros without losing 6.25 kHz precision");check(DiscoveryNames.Snap(channel.FrequencyHz,12500,600)==461412500,"Explicit channel grid corrects a measured offset inside tolerance");check(DiscoveryNames.Snap(channel.FrequencyHz,0,500)==channel.FrequencyHz&&DiscoveryNames.Snap(channel.FrequencyHz,12500,100)==channel.FrequencyHz,"Default and out-of-tolerance frequencies remain exact");
  var library=new FrequencyLibrary(Path.Combine(root,"library.json"));library.Upsert(folder);library.Upsert(channel);
  var tg=DiscoveryRecord.Create("talkgroup","DMR:Tier III:Network 5","91","Dispatch","DMR");var radio=DiscoveryRecord.Create("radio","DMR:Tier III:Network 5","123","Unit 123","DMR");var bundle=library.ExportDiscoveries(extra:[tg,radio]);
  check(bundle.Channels.Single(c=>!c.IsFolder).Notes==""&&bundle.Channels.Single(c=>!c.IsFolder).Activity?.Receiver=="","Share export removes notes by default and activity receiver identity");check(bundle.Records.Any(r=>r.Kind=="talkgroup")&&bundle.Records.Any(r=>r.Kind=="radio")&&bundle.Records.Any(r=>r.Kind=="site"),"Discovery bundle includes independent talkgroups, radio labels and inferred site records");
  check(library.ExportDiscoveries(backup:true).Channels.Single(c=>!c.IsFolder).Notes==channel.Notes,"Library backup retains notes");
  foreach(string extension in new[]{".mrsdiscovery",".json",".csv"}){string file=Path.Combine(root,"roundtrip"+extension);DiscoveryExchange.Write(file,bundle,extension==".csv");var read=DiscoveryExchange.Read(file);check(read.Channels.Count==2&&read.Channels.Single(c=>!c.IsFolder).FrequencyHz==channel.FrequencyHz,"Exact frequency/folder round trip "+extension);check(extension==".csv"||read.Records.Count==bundle.Records.Count,"Catalog relationship round trip "+extension);}
  string catalog=Path.Combine(root,"catalog.csv");DiscoveryExchange.Write(catalog,bundle,true,true);check(DiscoveryExchange.Read(catalog).Records.Count==bundle.Records.Count,"Catalog CSV independently preserves talkgroup/radio/system/site records");
  check(DiscoveryExchange.Read(Path.Combine(root,"library.json")).Channels.Count==2,"Existing version-one saved frequency file can be imported without starting over");
  var invalidId=channel with{SiteScope=null!};bool invalidRejected=false;try{DiscoveryExchange.Validate(bundle with{Channels=[folder,invalidId]});}catch(IOException){invalidRejected=true;}check(invalidRejected,"Missing scope metadata is rejected before import");
  var target=new FrequencyLibrary(Path.Combine(root,"imported.json"));var plan=target.PreviewImport(bundle);check(target.Items.Count==0&&plan.Changes.Any(c=>c.Action=="Add"),"Import preview has no write side effects");target.ApplyReview(plan);check(target.Items.Count==2&&target.Records.Count==bundle.Records.Count,"Approved import commits channels and catalog together");check(new FrequencyLibrary(Path.Combine(root,"imported.json")).Records.Count==bundle.Records.Count,"Catalog survives restart in the frequency library");
  check(target.PreviewImport(bundle).Changes.Count==0,"Repeated discovery import is idempotent");target.Undo();check(target.Items.Count==0&&target.Records.Count==0,"Undo restores both channels and catalog as a single batch");
  var cleanup=library.PreviewCleanup(true,true,true,12500,600);check(library.Items.Single(c=>!c.IsFolder).FrequencyHz==channel.FrequencyHz,"Cleanup preview does not mutate the saved list");string backup=library.ApplyReview(cleanup);var cleaned=library.Items.Single(c=>!c.IsFolder);check(cleaned.FrequencyHz==461412500&&cleaned.OriginalFrequencyHz==461413035&&cleaned.Notes==channel.Notes,"Cleanup preserves raw frequency and notes while applying selected snapping");check(cleaned.Name.Contains("Site 11")&&File.Exists(backup),"Cleanup produces an informative name and a timestamped backup");library.Undo();check(library.Items.Single(c=>!c.IsFolder)==channel,"Cleanup Undo restores original names, folders, frequency and metadata");
  var stale=library.PreviewCleanup(true,false,false,0,0);library.Upsert(channel with{Notes="Edited after preview"});bool rejected=false;try{library.ApplyReview(stale);}catch(IOException){rejected=true;}check(rejected,"Stale in-memory preview cannot overwrite later edits");
  var external=new FrequencyLibrary(Path.Combine(root,"library.json"));var diskPlan=external.PreviewCleanup(true,false,false,0,0);library.Upsert(channel with{Name="Newer disk edit"});rejected=false;try{external.ApplyReview(diskPlan);}catch(IOException){rejected=true;}check(rejected&&new FrequencyLibrary(Path.Combine(root,"library.json")).Items.Single(c=>!c.IsFolder).Name=="Newer disk edit","Another window's newer disk revision is preserved");
  var imports=new FrequencyLibrary(Path.Combine(root,"conflicts.json"));var local=channel with{Name="My saved label",Notes="Keep",FrequencyHz=461412500,Activity=null};imports.Upsert(folder);imports.Upsert(local);
  var incoming=local with{Name="Someone else's label",Notes="Replace?",BandwidthHz=12500,Signaling="Site 12; CC 7"};var conflict=imports.PreviewImport(new(DiscoveryExchange.Format,1,[folder,incoming],[]));imports.ApplyReview(conflict);var result=imports.Items.Single(c=>!c.IsFolder);check(conflict.Conflicts>0&&result.Name==local.Name&&result.Notes=="Keep"&&result.Signaling==local.Signaling&&result.BandwidthHz==12500,"Import fills missing fields and preserves conflicting nonblank local fields");
  var otherSite=local with{Id=Guid.NewGuid(),SiteScope="DMR:Tier III:Network 5:Site 12"};imports.ApplyReview(imports.PreviewImport(new(DiscoveryExchange.Format,1,[folder,otherSite],[])));check(imports.Items.Count(c=>!c.IsFolder)==2,"Same frequency at different sites is not merged");
  var duplicate=local with{Id=Guid.NewGuid(),Name="Observed carrier"};var duplicates=new FrequencyLibrary(Path.Combine(root,"duplicates.json"));duplicates.Upsert(folder);duplicates.Upsert(local);duplicates.Upsert(duplicate);var duplicatePlan=duplicates.PreviewCleanup(false,false,true,0,0);check(duplicatePlan.Channels.Count(c=>!c.IsFolder)==2&&duplicatePlan.Conflicts>0,"Conflicting duplicate labels are preserved for review");
  var simple=new FrequencyItem{Name="Observed carrier",FrequencyHz=451600000,Protocols="DMR",Signaling="Site 11; CC 4"};var exact=new FrequencyLibrary(Path.Combine(root,"exact.json"));exact.Upsert(simple);exact.Upsert(simple with{Id=Guid.NewGuid()});check(exact.PreviewCleanup(false,false,true,0,0).Channels.Count(c=>!c.IsFolder)==1,"Compatible exact duplicates can be consolidated");
  rejected=false;try{DiscoveryExchange.Validate(bundle with{Version=99});}catch(IOException){rejected=true;}check(rejected,"Unsupported discovery schema is rejected");
  rejected=false;try{DiscoveryExchange.Validate(bundle with{Channels=[folder with{ParentId=folder.Id}]});}catch(IOException){rejected=true;}check(rejected,"Malformed cyclic imported folders are rejected");
  string unsafeZip=Path.Combine(root,"unsafe.zip");using(var zip=ZipFile.Open(unsafeZip,ZipArchiveMode.Create)){using var writer=new StreamWriter(zip.CreateEntry("../frequencies.json").Open());writer.Write("{}");}rejected=false;try{DiscoveryExchange.Read(unsafeZip);}catch(IOException){rejected=true;}check(rejected,"Bundle rejects unexpected/traversal entries without extracting files");
  var scopeDb=new FrequencyLibrary(Path.Combine(root,"scoped-cleanup.json"));scopeDb.Upsert(folder);scopeDb.Upsert(channel);var selectedCleanup=scopeDb.PreviewCleanup(true,false,false,0,0,[folder.Id]);check(selectedCleanup.Changes.Count>0,"Selected-folder cleanup includes its descendants");
  var offScope=new FrequencyItem{Name="Observed carrier",FrequencyHz=462123456};scopeDb.Upsert(offScope);var scoped=scopeDb.PreviewCleanup(true,false,false,12500,600,[channel.Id]);check(scoped.Channels.Single(c=>c.Id==offScope.Id)==offScope,"Selected cleanup leaves unrelated entries untouched");
  var sibling=new FrequencyItem{Name="Unrelated",FrequencyHz=462000000,ParentId=folder.Id};library=new FrequencyLibrary(Path.Combine(root,"selected.json"));library.Upsert(folder);library.Upsert(channel);library.Upsert(sibling);var selected=library.ExportDiscoveries([channel.Id],extra:[tg,DiscoveryRecord.Create("talkgroup","P25:Other","1","Other","P25")]);check(selected.Channels.Count(c=>!c.IsFolder)==1&&selected.Channels.Any(c=>c.IsFolder)&&selected.Records.All(r=>r.Scope!="P25:Other"),"Selected export includes ancestors and related catalog only, without siblings or other systems");
 }
}
